  PRIMARY KEY (`id`),
  KEY `idx_chls_khoa` (`khoa`),
  KEY `idx_chls_luc` (`luc`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS `cau_hinh_nhom` (
  `ma` varchar(20) NOT NULL,
