  `monskilled` varchar(200) NOT NULL COMMENT 'so luong quai da giet',
  `isfinish` varchar(200) NOT NULL COMMENT 'da hoan thanh nhiem vu hay chua',
  `idsubRcv` varchar(200) DEFAULT NULL,
  `itemquest` varchar(1000) DEFAULT NULL,
  PRIMARY KEY (`id_char`)
