CREATE TABLE IF NOT EXISTS `tob_char_thach_dau` (
  `id` int(10) unsigned NOT NULL,
  `charname` varchar(45) NOT NULL,
  `point` int(10) unsigned NOT NULL DEFAULT 0,
  `lv` int(10) unsigned NOT NULL DEFAULT 1,
