DROP TABLE IF EXISTS `data_noi_dung_trang_bi`;
CREATE TABLE `data_noi_dung_trang_bi` (
  `ma` varchar(255) NOT NULL,
  `bac` bigint NOT NULL,
  `ten_bac` varchar(255) NOT NULL,
