  `bat` TINYINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`ma`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

ON DUPLICATE KEY UPDATE `ten` = VALUES(`ten`), `he` = VALUES(`he`), `kieu` = VALUES(`kieu`), `vai_tro` = VALUES(`vai_tro`), `pt_sat_thuong` = VALUES(`pt_sat_thuong`), `so_don` = VALUES(`so_don`), `hoi_chieu_ms` = VALUES(`hoi_chieu_ms`), `pp` = VALUES(`pp`), `trang_thai` = VALUES(`trang_thai`), `ti_le_tt_phan_nghin` = VALUES(`ti_le_tt_phan_nghin`), `hinh_dang` = VALUES(`hinh_dang`), `tam_xa` = VALUES(`tam_xa`), `rong` = VALUES(`rong`), `hieu_ung` = VALUES(`hieu_ung`), `mau` = VALUES(`mau`), `doi_mau` = VALUES(`doi_mau`), `dac_trung_ho` = VALUES(`dac_trung_ho`), `goc` = VALUES(`goc`);

