INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('ban_do.khoa.bat', 'che_do', 'Khoá bản đồ theo cấp / cửa ải', '1 = bản đồ cần đủ cấp và xong cửa ải (bảng data_ban_do_mo_khoa) mới vào được, kèm luật Tự động đánh theo bản đồ; 0 = mở mọi bản đồ (người chơi cũ luôn được miễn trừ theo cấp).', 'co', '1', '{}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.KhoaBanDoGame', 338, 'luon_bat', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('pvp.ngam_tay', 'pvp', 'Ngắm tay trong PvP', '1 = trận giữa người chơi (PK, thách đấu, xếp hạng, sàn đấu, chiến trường, chiếm Gym) không tự động đánh, không tự nhắm: kéo chiêu để ngắm, chiêu bay thẳng theo hướng kéo (client 0.9.8; bản cũ bắn theo hướng Pokémon đang quay). 0 = như 0.9.7.', 'co', '1', '{}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.BanHuongGame', 339, 'luon_bat', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('pvp.ngam_tay.giay_giao_chien', 'pvp', 'Giây coi là đang giao chiến PvP', 'Đánh trúng / bị người chơi đánh trúng trong ngần này giây thì vẫn tính là trận giữa người chơi (tắt tự động, bắt buộc ngắm tay).', 'so', '10', '{"min": 0, "max": 600}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.BanHuongGame', 340, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('pvp.ngam_tay.bu_tre_ms', 'pvp', 'Bù trễ vị trí (ms)', 'Vị trí mục tiêu trong ngần này ms trước lúc đạn tới đều tính trúng (ưu tiên người bắn khi mạng trễ). Trần 300.', 'so', '150', '{"min": 0, "max": 300}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.BanHuongGame', 341, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('pvp.ngam_tay.map', 'pvp', 'Bản đồ PvP bắt buộc ngắm tay (id)', 'Ngoài sàn đấu / chiến trường / giải Liên minh / thách đấu / chiếm Gym đang đánh (tự nhận theo loại bản đồ). So cả id bản đồ lẫn id nạp.', 'ds_so', '202,204,205,227', '{"min": 0, "max": 100000}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.BanHuongGame', 342, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('dat_ten_pet.bat', 'dat_ten_pet', 'Bật thẻ đặt tên Pokémon', 'Khẩn cấp (server.ini): 0 = không dùng / không bán thẻ (dòng đã có vẫn tính, vẫn trong trần).', 'co', '1', '{}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.DatTenPetGame', 343, 'luon_bat', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('dat_ten_pet.gia_luong', 'dat_ten_pet', 'Giá thẻ (lượng)', 'Cửa hàng lượng (mục Tiện ích). Bản kiếm được: đổi Tem nghiên cứu / lượng khoá ở Sổ tay (data_cua_hang_lau_dai).', 'so', '100', '{"min": 10, "max": 5000}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.DatTenPetGame.giaLuong', 344, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('dat_ten_pet.mua_tuan_toi_da', 'dat_ten_pet', 'Số thẻ mua bằng lượng / tuần', 'Mỗi Pokémon, mở lại thứ Hai. 0 = tạm ngừng bán. Giới hạn số lần quay lại dòng bằng tiền.', 'so', '3', '{"min": 0, "max": 20}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'com.htbb.pokemon.NapTienGame.mua', 345, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('dat_ten_pet.muc_phan_nghin', 'dat_ten_pet', 'Các mức của dòng (‰)', 'Tăng dần, mỗi mức ≤ trần một dòng. 10 = +1%. Chí mạng / né nhân thêm hệ số của bảng data_dong_the_ten.', 'ds_so', '10,15,20,30', '{"min": 1, "max": 30}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'com.htbb.pokemon.DatTenPet.quay', 346, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('dat_ten_pet.trong_so_muc', 'dat_ten_pet', 'Trọng số từng mức', 'Cùng số phần tử với các mức, KHÔNG tăng (mức thấp luôn ra nhiều hơn). Sai luật thì máy chủ dùng mặc định 55,30,12,3.', 'ds_so', '55,30,12,3', '{"min": 1, "max": 1000}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'com.htbb.pokemon.DatTenPet.mucHopLe', 347, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('dat_ten_pet.tran_dong_phan_nghin', 'dat_ten_pet', 'Trần một dòng thẻ tên (‰)', 'Ngân sách ô thẻ tên pet. 30 = +3%.', 'so', '30', '{"min": 0, "max": 60}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.DatTenPetGame.tranDong', 348, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('trang_tri.tran_tong_phan_nghin', 'dat_ten_pet', 'Trần tổng chỉ số trang trí (‰)', 'Mọi ô trang trí cộng lại (thiết kế cân bằng 4.5), nằm trong chi_so.tran_phan_tram_cong. 50 = 5%.', 'so', '50', '{"min": 0, "max": 50}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.DatTenPetGame.tranTrangTri', 349, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('dat_ten_pet.do_dai_toi_thieu', 'dat_ten_pet', 'Tên pet: ít nhất (ký tự)', '', 'so', '2', '{"min": 1, "max": 12}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'com.htbb.pokemon.DatTenPet.kiemTen', 350, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('dat_ten_pet.do_dai_toi_da', 'dat_ten_pet', 'Tên pet: nhiều nhất (ký tự)', 'Cột tob_pet_dat_ten.ten dài 40.', 'so', '12', '{"min": 2, "max": 20}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'com.htbb.pokemon.DatTenPet.kiemTen', 351, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('dat_ten_pet.ban_client_popup', 'dat_ten_pet', 'Bản client có hộp kết quả thẻ tên', 'Client có số bản ≥ giá trị này nhận gói -106 (thẻ trắng kiểu Pokémon GO); cũ hơn / Unity nhận hộp thông báo 37.', 'so', '908', '{"min": 0, "max": 100000}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.DatTenPetGame.baoKetQua', 352, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('loai.bat', 'loai', 'Loài riêng từng con quái', '1 = khi quái thường hồi sinh, máy chủ có thể đổi loài hiển thị theo vùng sinh thái + dải cấp + bậc hiếm (data_loai_vung). Cấp, HP, TTK của quái không đổi. 0 = mọi quái mang loài mặc định của mẫu.', 'co', '1', '{}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.LoaiQuaiGame', 353, 'luon_bat', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('loai.ban_client', 'loai', 'Bản client tối thiểu thấy loài riêng', 'Client có số bản nhỏ hơn chỉ thấy loài mặc định của mẫu quái (gói -125 không gửi; Pokédex ghi loài mặc định).', 'so', '908', '{"min": 0, "max": 99999}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.LoaiQuaiGame', 354, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('loai.doi_thuong_phan_tram', 'loai', 'Quái thường đổi loài T1–T2 (%)', '% lần hồi sinh của quái thường được đổi sang một loài Phổ biến / Không phổ biến khác của vùng (quần thể vùng). 0 = chỉ còn lượt gặp loài hiếm.', 'so', '30', '{"min": 0, "max": 100}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.LoaiQuaiGame', 355, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('loai.gap_t3', 'loai', 'Gặp loài T3: 1 / N lần hồi sinh', 'Spec 2.4: 100.', 'so', '100', '{"min": 1, "max": 1000000}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.LoaiQuaiGame', 356, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('loai.gap_t4', 'loai', 'Gặp loài T4: 1 / N lần hồi sinh', 'Spec 2.4: 600.', 'so', '600', '{"min": 1, "max": 1000000}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.LoaiQuaiGame', 357, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('loai.gap_t5', 'loai', 'Gặp loài T5: 1 / N lần hồi sinh', 'Spec 2.4: 4.000, và chỉ khi đúng khung giờ hoặc đúng thời tiết của loài.', 'so', '4000', '{"min": 1, "max": 10000000}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.LoaiQuaiGame', 358, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('loai.he_so_toi_da_phan_tram', 'loai', 'Trần hệ số gặp (%)', 'Tích các hệ số (giờ ít người ×1,5, thời tiết hợp hệ ×1,5) bị kẹp ở mức này. Spec 2.4: ×3.', 'so', '300', '{"min": 100, "max": 1000}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.LoaiQuaiGame', 359, 'co_dinh', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('loai.sprite_kb_giay', 'loai', 'Tốc độ gửi hình theo nhu cầu (KB/giây/người)', 'Trần băng thông gói -126 cho mỗi client (spec 3.5: 64).', 'so', '64', '{"min": 4, "max": 4096}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.LoaiMayChu', 360, 'co_dinh', 1);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('kinh_te', 'Kinh tế: tỉ lệ rơi & EXP', 'Tỉ lệ rơi xu / lượng / đồ và EXP quái. Áp dụng ngay. Thuế, phí và công thức kinh tế cốt lõi đã cố định (không hiện ở đây).', 1, 0);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('su_kien', 'Sự kiện & giftcode', 'Giờ chiếm Gym, trần & ngân sách giftcode. Bật/tắt từng sự kiện ở trang Sự kiện (bảng tob_su_kien).', 2, 0);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('nap_tien', 'Nạp tiền', 'Công tắc bán từng loại sản phẩm, trần chi tiêu. Web vẫn KHOÁ (fail closed) khi thiếu HTBB_NAP_BAT, giấy phép hoặc bí mật cổng thanh toán — các giá trị đó nằm trong biến môi trường, không ở CSDL.', 3, 0);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('thanh_vien', 'Thành viên & kích hoạt', 'Thành viên HTBB theo tài khoản (trả phí) và Kích hoạt tài khoản (miễn phí): tính năng bị khoá, giá, thời hạn, chặn đăng nhập.', 4, 0);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('chong_clone', 'Chống clone & chuyển xu', 'Cổng cho mọi đường chuyển xu / giá trị giữa hai người chơi (giao dịch, ký gửi, thú cưng lấy xu, chợ trang trí, chợ sinh thái, thách đấu): cấp, tuổi tài khoản, giờ chơi, giới hạn cùng thiết bị, giá ký gửi. Nhật ký + báo cáo "Nghi clone" ở /admin/kinh-te.', 5, 0);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('vong_quay', 'Vòng quay may mắn (cố định)', 'Ba vòng quay góp hũ (thường / VIP bằng xu, lượng): người thắng nhận hũ trừ phí, phí là hố hút. Không in tiền: hũ = tổng cược; chỉ 1 người thì hoàn lại. Cổng chống clone áp như giao dịch xu (cấp, tuổi tài khoản, giờ chơi, tối đa N Pokémon cùng thiết bị / IP mỗi ngày). Mức cược, trần ngày, phí là công thức kinh tế cốt lõi: cố định (đổi khẩn cấp bằng server.ini).', 6, 1);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('cuoc_xu', 'Thách đấu cược xu & lì xì (cố định)', 'Thách đấu cược xu 1-1 và nhóm (ký quỹ hai bên, phí bên thắng là hố hút, hoà hoàn đủ, mức theo cấp) và lì xì Tết (bao: trần nhận / mở theo ngày và đợt, xu theo giờ thu nhập; mã: lượng khoá, mỗi tài khoản / thiết bị / IP một lần, trần tổng). Công thức kinh tế cốt lõi: cố định (đổi khẩn cấp bằng server.ini).', 7, 1);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('tu_dong', 'Tự động đánh & hồi sinh', 'Giới hạn Tự động đánh (chỉ khi online) và giá hồi sinh tại chỗ. Luật an toàn (cấm ở PvP / Gym / boss, nhịp, bán kính…) đã cố định.', 8, 0);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('bao_tri', 'Máy chủ, đăng ký & bảo trì', 'Bảo trì, đăng ký, bản client tối thiểu, link website / tải game, GM, ngày khai trương.', 9, 0);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('che_do', 'Chế độ game (cố định)', 'Chế độ lớn luôn bật trên máy thật (dài hạn, hệ sinh thái). Đổi = sửa server.ini khi khẩn cấp.', 10, 1);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('dang_ky', 'Đăng ký (cố định)', 'Tham số nội bộ của đăng ký trong game.', 11, 1);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('chong_spam', 'Chống spam, DoS & nhật ký (cố định)', 'Nhịp chat/thao tác, chống ngập kết nối/gói tin, mức nhật ký.', 12, 1);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('pvp', 'PvP / Gym / Hầm Ngục (luôn bật)', 'Nội dung chiến đấu dài hạn.', 13, 1);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('hoc_chieu', 'Học chiêu & Điểm huấn luyện (cố định)', 'Chiêu học theo loài (bảng data_learnset), Điểm huấn luyện thay điểm tiềm năng tự do (data_huan_luyen, data_tang_truong_dong). Số liệu trong bảng dữ liệu; ở đây chỉ có công tắc và giá tẩy điểm.', 14, 1);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('chi_so', 'Chỉ số & chống lạm phát (cố định)', 'Trần + giảm dần cho chỉ số trang bị, pet, thú cưỡi, skin (docs/thiet-ke-game.md).', 15, 1);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('trang_bi', 'Trang bị, ngọc hệ, chế tạo & thu phục (cố định)', 'Bộ cùng bậc, ngọc hệ, chế tạo, mốc neo nâng cấp, thu phục Pokémon (docs/thiet-ke-game.md 4.2, 4.3, 7.7).', 16, 1);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('hoi_sinh', 'Hồi sinh — luật (cố định)', 'Phạt khi về Trung tâm, mệt mỏi, cấm hồi sinh tại chỗ ở PvP / Gym / boss / Mê cung.', 17, 1);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('thong_bao', 'Thông báo (cố định)', 'Gộp thông báo toàn máy chủ.', 18, 1);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('quan_tri', 'Quản trị & thử nghiệm (cố định)', 'Cờ GM cũ và khoá thử nghiệm (máy thật luôn mặc định).', 19, 1);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('dat_ten_pet', 'Thẻ đặt tên Pokémon', 'Giá bán (lượng), số lần mua / tuần và tỉ lệ các mức của dòng chỉ số ngẫu nhiên. Trần một dòng và trần tổng trang trí 5% là cố định. Bảng chỉ số trong data_dong_the_ten, từ cấm trong data_tu_cam_ten.', 20, 1);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('loai', 'Loài Pokémon hoang dã', 'Loài riêng từng con quái khi hồi sinh (6 bậc T1–T6, tỉ lệ gặp theo bậc), tải hình theo nhu cầu. Dữ liệu loài ở bảng data_loai* (sql/nang_cap.sql, khối them_loai_day_du.sql).', 21, 1);
